package com.newuniverse.nusmp.labyrinth.loot;

import net.minecraft.network.chat.Component;
import net.minecraft.network.chat.MutableComponent;

import java.util.Map;

/**
 * GENERATED by tools/loot/gen_data.py (edit the python, not this file). Why: every line the loot says (a tooltip, a message) must be a TRANSLATABLE component, so each player
 * reads it in their own language, and must still read properly before the lang fragment is merged or when a key is missing. {@code translatableWithFallback} does both
 * if it is given the English text; this map is that text, the same one the lang fragment tools/lang/squad_loot.json is written from, so no call site repeats an English string.
 */
final class LootText {
    private LootText() {}

    static final Map<String, String> ENGLISH = Map.ofEntries(
            Map.entry("message.nusmp.loot.coated", "The venom soaks into the edge."),
            Map.entry("message.nusmp.loot.nothing_to_sell", "The Merchant has no use for that."),
            Map.entry("message.nusmp.loot.repaired", "The core flares and the metal is whole again."),
            Map.entry("message.nusmp.loot.shop_off", "The Merchant is not trading."),
            Map.entry("message.nusmp.loot.sold", "Sold %1$s for %2$s."),
            Map.entry("message.nusmp.loot.tempered", "The shard sinks into the metal. Shadow-tempered."),
            Map.entry("tooltip.nusmp.loot.armor", "%1$s armor"),
            Map.entry("tooltip.nusmp.loot.damage", "%1$s attack damage (%2$s grade)"),
            Map.entry("tooltip.nusmp.loot.effect", "%1$s (%2$s)"),
            Map.entry("tooltip.nusmp.loot.grade.normal", "normal"),
            Map.entry("tooltip.nusmp.loot.grade.rare", "rare"),
            Map.entry("tooltip.nusmp.loot.grade.special", "special"),
            Map.entry("tooltip.nusmp.loot.header", "%1$s - found on floor %2$s"),
            Map.entry("tooltip.nusmp.loot.rarity.common", "Common"),
            Map.entry("tooltip.nusmp.loot.rarity.epic", "Epic"),
            Map.entry("tooltip.nusmp.loot.rarity.legendary", "Legendary"),
            Map.entry("tooltip.nusmp.loot.rarity.rare", "Rare"),
            Map.entry("tooltip.nusmp.loot.rarity.uncommon", "Uncommon"),
            Map.entry("tooltip.nusmp.loot.restores_aura", "Restores %1$s%% of your aura"),
            Map.entry("tooltip.nusmp.loot.restores_mana", "Restores %1$s%% of your magicules"),
            Map.entry("tooltip.nusmp.loot.sell_hint", "Sneak and use on a Hub Merchant to sell"),
            Map.entry("tooltip.nusmp.loot.speed", "%1$s attacks per second"),
            Map.entry("tooltip.nusmp.loot.stat.armor", "+%1$s armor"),
            Map.entry("tooltip.nusmp.loot.stat.attack_damage", "+%1$s attack damage"),
            Map.entry("tooltip.nusmp.loot.stat.attack_speed", "+%1$s attack speed"),
            Map.entry("tooltip.nusmp.loot.stat.crit_chance", "+%1$s%% critical chance"),
            Map.entry("tooltip.nusmp.loot.stat.mana", "+%1$s%% maximum magicules"),
            Map.entry("tooltip.nusmp.loot.stat.mana_regen", "+%1$s%% magicule regeneration"),
            Map.entry("tooltip.nusmp.loot.stat.max_health", "+%1$s max health"),
            Map.entry("tooltip.nusmp.loot.stat.move_speed", "+%1$s%% movement speed"),
            Map.entry("tooltip.nusmp.loot.tempered", "Shadow-tempered"),
            Map.entry("tooltip.nusmp.loot.use.golem_core", "Anvil: fully repairs a damaged tool, weapon or armour piece"),
            Map.entry("tooltip.nusmp.loot.use.shadow_core_shard", "Anvil: works one extra stat line into a piece of loot gear"),
            Map.entry("tooltip.nusmp.loot.use.venom_sac", "Anvil: coats a weapon, its next twenty strikes poison"),
            Map.entry("tooltip.nusmp.loot.value", "Sells for %1$s"),
            Map.entry("tooltip.nusmp.loot.venom", "Venom-coated: %1$s strikes left"),
            Map.entry("tooltip.nusmp.loot.worn_in", "Worn in the %1$s slot"));

    static MutableComponent text(String key, Object... args) {
        return Component.translatableWithFallback(key, ENGLISH.getOrDefault(key, key), args);
    }

    static String english(String key) { return ENGLISH.getOrDefault(key, key); }
}
